From 639fe4ecdf8ffac97b75e638cde1e87fcffe2c2f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:04:22 +0100
Subject: [PATCH] kded/secretagent: show a password dialog for every pending
 request

The agent kept a single dialog and queued every other secrets request
until it was closed, so an idle VPN dialog kept the Wi-Fi password
dialog from appearing. Each request now owns its dialog instead.

BUG: 400760
---
 kded/secretagent.cpp | 39 +++++++++++++++++----------------------
 kded/secretagent.h   |  1 -
 2 files changed, 17 insertions(+), 23 deletions(-)

diff --git a/kded/secretagent.cpp b/kded/secretagent.cpp
index 689c0d2da..ddb22dcbc 100644
--- a/kded/secretagent.cpp
+++ b/kded/secretagent.cpp
@@ -49,7 +49,6 @@ QString storageKey(const NetworkManager::ConnectionSettings &settings, const QSt

 SecretAgent::SecretAgent(QObject *parent)
     : NetworkManager::SecretAgent(QStringLiteral("org.kde.plasma.networkmanagement"), NetworkManager::SecretAgent::Capability::VpnHints, parent)
-    , m_dialog(nullptr)
 {
     connect(NetworkManager::notifier(), &NetworkManager::Notifier::serviceDisappeared, this, &SecretAgent::killDialogs);

@@ -148,9 +147,6 @@ void SecretAgent::CancelGetSecrets(const QDBusObjectPath &connection_path, const
     for (int i = 0; i < m_calls.size(); ++i) {
         auto request = m_calls.at(i);
         if (request->type == SecretsRequest::GetSecrets && callId == request->callId) {
-            if (m_dialog == request->dialog) {
-                m_dialog = nullptr;
-            }
             delete request->dialog;
             sendError(SecretAgent::AgentCanceled, QStringLiteral("Agent canceled the password dialog"), request->message);
             m_calls.removeAt(i);
@@ -163,9 +159,10 @@ void SecretAgent::CancelGetSecrets(const QDBusObjectPath &connection_path, const

 void SecretAgent::dialogAccepted()
 {
+    auto dialog = qobject_cast<PasswordDialog *>(sender());
     for (int i = 0; i < m_calls.size(); ++i) {
         auto request = m_calls[i];
-        if (request->type == SecretsRequest::GetSecrets && request->dialog == m_dialog) {
+        if (request->type == SecretsRequest::GetSecrets && request->dialog == dialog) {
             NMStringMap tmpOpenconnectSecrets;
             NMVariantMapMap connection = request->dialog->secrets();
             if (connection.contains(QStringLiteral("vpn"))) {
@@ -271,25 +268,24 @@ void SecretAgent::dialogAccepted()
         }
     }

-    m_dialog->deleteLater();
-    m_dialog = nullptr;
+    dialog->deleteLater();

     processNext();
 }

 void SecretAgent::dialogRejected()
 {
+    auto dialog = qobject_cast<PasswordDialog *>(sender());
     for (int i = 0; i < m_calls.size(); ++i) {
         auto request = m_calls[i];
-        if (request->type == SecretsRequest::GetSecrets && request->dialog == m_dialog) {
+        if (request->type == SecretsRequest::GetSecrets && request->dialog == dialog) {
             sendError(SecretAgent::UserCanceled, QStringLiteral("User canceled the password dialog"), request->message);
             m_calls.removeAt(i);
             break;
         }
     }

-    m_dialog->deleteLater();
-    m_dialog = nullptr;
+    dialog->deleteLater();

     processNext();
 }
@@ -340,7 +336,7 @@ void SecretAgent::processNext()

 bool SecretAgent::processGetSecrets(QSharedPointer<SecretsRequest> request)
 {
-    if (m_dialog) {
+    if (request->dialog) {
         return false;
     }

@@ -444,21 +440,20 @@ bool SecretAgent::processGetSecrets(QSharedPointer<SecretsRequest> request)
         return true;
     } else if (requestNew || (allowInteraction && !setting->needSecrets(requestNew).isEmpty()) || (allowInteraction && userRequested)
                || (isVpn && allowInteraction)) {
-        m_dialog = new PasswordDialog(connectionSettings, request->flags, request->setting_name, request->hints);
-        connect(m_dialog, &PasswordDialog::accepted, this, &SecretAgent::dialogAccepted);
-        connect(m_dialog, &PasswordDialog::rejected, this, &SecretAgent::dialogRejected);
-
-        if (m_dialog->hasError()) {
-            sendError(m_dialog->error(), m_dialog->errorMessage(), request->message);
-            delete m_dialog;
-            m_dialog = nullptr;
+        auto dialog = new PasswordDialog(connectionSettings, request->flags, request->setting_name, request->hints);
+        connect(dialog, &PasswordDialog::accepted, this, &SecretAgent::dialogAccepted);
+        connect(dialog, &PasswordDialog::rejected, this, &SecretAgent::dialogRejected);
+
+        if (dialog->hasError()) {
+            sendError(dialog->error(), dialog->errorMessage(), request->message);
+            delete dialog;
             return true;
         } else {
-            request->dialog = m_dialog;
+            request->dialog = dialog;
             request->saveSecretsWithoutReply = !connectionSettings->permissions().isEmpty();
-            m_dialog->show();
+            dialog->show();
             if (KWindowSystem::isPlatformX11()) {
-                KX11Extras::setState(m_dialog->winId(), NET::KeepAbove);
+                KX11Extras::setState(dialog->winId(), NET::KeepAbove);
             }
             return false;
         }
diff --git a/kded/secretagent.h b/kded/secretagent.h
index d82fe1e31..4356d425d 100644
--- a/kded/secretagent.h
+++ b/kded/secretagent.h
@@ -101,7 +101,6 @@ private:
     bool hasSecrets(const NMVariantMapMap &connection) const;
     void sendSecrets(const NMVariantMapMap &secrets, const QDBusMessage &message) const;

-    mutable PasswordDialog *m_dialog;
     QList<QSharedPointer<SecretsRequest>> m_calls;

     void importSecretsFromPlainTextFiles();
-- 
